import { expect, test, uniqueName } from "../../fixtures";

test.describe("vendor audit trail", () => {
  test(
    "audit events are listed oldest first with actor and action",
    { tag: "@AUD-01" },
    async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const vendorName = uniqueName("Audit Vendor");

      const createResponse = await member.post("/api/vendors", {
        data: {
          name: vendorName,
          category: "software",
          contact_email: `ap+${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@northwind.test`,
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();

      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9.pdf",
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4\n% audit trail test W-9\n%%EOF\n"),
          },
        },
      });
      expect(uploadResponse.status()).toBe(201);

      // Act: extraction may complete asynchronously, so poll until the trail settles.
      const expectedActions = ["vendor.created", "document.uploaded", "document.extracted"];
      let finalResponse;
      await expect
        .poll(
          async () => {
            finalResponse = await member.get(`/api/vendors/${vendor.id}/audit`);
            if (finalResponse.status() !== 200) return [];
            const body = await finalResponse.json();
            return (body.items as { action: string }[]).map((e) => e.action);
          },
          { timeout: 30_000, intervals: [500, 1000, 2000] },
        )
        .toEqual(expectedActions);

      // Assert
      expect(finalResponse!.status()).toBe(200);
      const trail = await finalResponse!.json();
      const events = trail.items as {
        action: string;
        at: string;
        actor: { id: string; name: string; email: string };
      }[];

      expect(events.map((e) => e.action)).toEqual(expectedActions);

      for (const event of events) {
        expect(event.actor.id).toBeTruthy();
        expect(event.actor.name).toBeTruthy();
        expect(event.actor.email).toBe("member@northwind.test");
        expect(Number.isNaN(Date.parse(event.at))).toBe(false);
      }

      const times = events.map((e) => Date.parse(e.at));
      for (let i = 1; i < times.length; i++) {
        expect(times[i]).toBeGreaterThanOrEqual(times[i - 1]);
      }
    },
  );
});
